public static TFMLockedOrders find(TFMBackendId _backendid, TFMOrderTypes _ordertype, boolean _forUpdate = false)
{
    TFMLockedOrders  mobLockedOrders;

    mobLockedOrders.selectForUpdate  (_forUpdate);
    mobLockedOrders.selectLocked     (_forUpdate);

    select firstonly mobLockedOrders
        index hint BackendOrderIdx
        where mobLockedOrders.BackendId == _backendid &&
                (mobLockedOrders.OrderType == _ordertype || !_ordertype);

    return mobLockedOrders;
}

public static boolean exist(TFMBackendId _backendid, TFMDocumentDeviceId _deviceId, UserId _userId)
{
    TFMLockedOrders  mobLockedOrders;

    select firstonly mobLockedOrders
        index hint BackendOrderIdx
        where mobLockedOrders.BackendId == _backendid &&
              (mobLockedOrders.DeviceId  == _deviceId   || !_deviceId) &&
              (mobLockedOrders.UserID    == _userId     || !_userId);

    return mobLockedOrders.recid;
}

public static boolean isOrderLocked(TFMBackendId _backendid, TFMDocumentDeviceId _deviceId, TFMLockingLevel _lockingLevel, UserId _userId = curUserId())
{
    TFMLockedOrders  mobLockedOrders;
    TFMDocumentDeviceId usedDeviceId = _lockingLevel == TFMLockingLevel::User ? '' : _deviceId;
    UserId usedUserId = _lockingLevel == TFMLockingLevel::Device ? '' : _userId;

    if (_lockingLevel == TFMLockingLevel::Never)
    {
        return false;
    }

    select firstonly mobLockedOrders
        index hint BackendOrderIdx
        where mobLockedOrders.BackendId == _backendid;

    if (!mobLockedOrders)
    {
        return false;
    }
    else if (_lockingLevel == TFMLockingLevel::User)
    {
        return mobLockedOrders.UserID != _userId;
    }
    else if (_lockingLevel == TFMLockingLevel::Device)
    {
        return mobLockedOrders.DeviceId != _deviceId;
    }
    else
    {
        return !(mobLockedOrders.DeviceId == _deviceId && mobLockedOrders.UserID == _userId);
    }

    return mobLockedOrders.recid;
}

public static void unlock(TFMBackendId _backendid, TFMOrderTypes _ordertype)
{
    TFMLockedOrders lockedOrder;
    ttsbegin;
    lockedOrder = TFMLockedOrders::find(_backendid,_ordertype,true);
    if (lockedOrder.recId)
    {
        lockedOrder.doDelete();
    }
    ttscommit;
}
